insert into public.exam_questions (id, module, question, options, answer, explanation) values
  (1, 'anatomia', 'Quale parte produce la lamina ungueale?', '["Il letto ungueale","La matrice","L''iponichio","L''eponichio"]'::jsonb, 1, 'La matrice è il tessuto vivo che produce la lamina; la lunula ne è la parte visibile.'),
  (2, 'anatomia', 'Cosa si rimuove durante la preparazione?', '["L''eponichio","La cuticola (pelle morta sulla lamina)","L''iponichio","Le pieghe laterali"]'::jsonb, 1, 'Si rimuove solo la cuticola morta; eponichio e iponichio sono tessuti vivi.'),
  (3, 'anatomia', 'Dove si trova il punto di stress?', '["Alla base, sotto la cuticola","Dove il bordo libero si stacca dal letto","Al centro della lunula","Sotto la matrice"]'::jsonb, 1, 'È la zona in cui il bordo libero lascia il letto: lì sopra va l''apex.'),
  (4, 'anatomia', 'Quanto cresce in media un''unghia della mano?', '["Circa 3 mm al mese","Circa 1 cm al mese","Circa 1 mm all''anno","Circa 365 mm all''anno"]'::jsonb, 0, 'Circa 0,1 mm al giorno, cioè 3 mm al mese.'),
  (5, 'anatomia', 'Una cliente ha un''unghia ispessita, giallastra e friabile. Cosa fai?', '["Copro con un gel coprente","Lavoro solo sulle altre dita","Rifiuto il servizio, disinfetto e la invio allo specialista","Limo via la parte malata"]'::jsonb, 2, 'Il sospetto di onicomicosi è una controindicazione assoluta.'),
  (6, 'anatomia', 'Una macchia verde sotto la ricostruzione indica di solito…', '["Muffa innocua","Un''infezione batterica (Pseudomonas)","Un colore difettoso","Una reazione alla lampada"]'::jsonb, 1, 'È un''infezione batterica: rimuovi il prodotto e invia al medico.'),
  (7, 'anatomia', 'Perché non si deve assottigliare la lamina naturale?', '["Perché diventa lucida","Perché isola meno dal calore e si indebolisce","Perché cresce più veloce","Non c''è nessun motivo"]'::jsonb, 1, 'Una lamina sottile espone a picchi di calore e danni.'),
  (8, 'anatomia', 'Quale parte dell''unghia produce la cuticola?', '["La matrice","L''eponichio","L''iponichio","Il letto ungueale"]'::jsonb, 1, 'L''eponichio è pelle viva sotto la piega prossimale: produce la cuticola, che invece è morta.'),
  (9, 'anatomia', 'Quali sono i quattro "sigilli" che proteggono l''unghia?', '["Lunula, matrice, letto, lamina","Cuticola con piega prossimale, due pieghe laterali, iponichio","Bordo libero, apex, punto di stress, lunula","Solo la cuticola"]'::jsonb, 1, 'Sono le barriere contro germi e sostanze: non si tagliano e non si forzano.'),
  (10, 'anatomia', 'Una matrice più lunga produce una lamina…', '["Più sottile","Più spessa","Più corta","Più colorata"]'::jsonb, 1, 'Più lunga è la matrice, più strati produce: la lamina è più spessa. Lo spessore naturale non si può cambiare.'),
  (11, 'anatomia', 'Dopo 3 settimane, quanta ricrescita ti aspetti in media sulle mani?', '["Circa 0,2 mm","Circa 2–2,5 mm","Circa 1 cm","Circa 5 mm"]'::jsonb, 1, 'Circa 0,8 mm a settimana: in 3 settimane circa 2,4 mm.'),
  (12, 'anatomia', 'Quale di questi segni di una banda scura sull''unghia richiede il dermatologo con urgenza?', '["Bande sottili e uguali su più dita da anni","Pigmento che si estende sulla pelle intorno all''unghia","Una macchia viola che si sposta in avanti dopo un colpo","Macchioline bianche"]'::jsonb, 1, 'Il pigmento sulla piega (segno di Hutchinson) è un segnale d''allarme: non coprire e consiglia subito il dermatologo.'),
  (13, 'anatomia', 'Le linee di Beau (solchi trasversali) sono…', '["Un''infezione contagiosa","Un disturbo dovuto a un rallentamento temporaneo della matrice: si può lavorare con delicatezza","Il segno di un''allergia agli acrilati","Una forma di micosi"]'::jsonb, 1, 'Si formano dopo febbre, malattie o traumi; non sono contagiose. Non si "livellano" con la lima.'),
  (14, 'igiene', 'Quale trattamento elimina anche le spore?', '["Sanificazione","Disinfezione","Sterilizzazione","Detersione"]'::jsonb, 2, 'Solo la sterilizzazione (autoclave) elimina ogni forma di vita.'),
  (15, 'igiene', 'Quale autoclave è adatta a strumenti imbustati, cavi e porosi?', '["Classe N","Classe B","Qualsiasi forno","Sterilizzatrice a sfere"]'::jsonb, 1, 'L''autoclave di classe B (EN 13060) gestisce carichi imbustati, cavi e porosi.'),
  (16, 'igiene', 'Quali guanti proteggono dai monomeri?', '["Lattice","Vinile","Nitrile","Cotone"]'::jsonb, 2, 'Il lattice non protegge dai monomeri: usa il nitrile.'),
  (17, 'igiene', 'Dal 1° settembre 2025 nell''UE è vietato nei cosmetici…', '["L''HEMA","Il TPO","L''acetone","L''EMA"]'::jsonb, 1, 'Il Reg. UE 2025/877 vieta TPO e DMTA, anche per uso professionale e per le scorte.'),
  (18, 'igiene', 'L''HEMA nei prodotti per unghie è…', '["Vietato del tutto","Libero per tutti","Ammesso solo per uso professionale con avvertenze","Ammesso solo nei top"]'::jsonb, 2, 'Reg. UE 2020/1682: uso professionale, con avvertenza sulle reazioni allergiche.'),
  (19, 'igiene', 'Quando è concreto il rischio di allergia agli acrilati?', '["Quando il prodotto polimerizzato è sulla lamina","Quando il prodotto non polimerizzato tocca la pelle","Solo con la lampada LED","Mai"]'::jsonb, 1, 'Il contatto della pelle con prodotto non polimerizzato sensibilizza.'),
  (20, 'igiene', 'In Italia la ricostruzione unghie in proprio richiede…', '["Solo un attestato privato","La qualifica di estetista e la SCIA","Nessun requisito","La partita IVA e basta"]'::jsonb, 1, 'Rientra nell''attività di estetista (L. 1/1990); l''apertura avviene con SCIA.'),
  (21, 'igiene', 'Che cosa significa "tempo di contatto" di un disinfettante?', '["Quanto dura il flacone aperto","Per quanti minuti la superficie deve restare bagnata perché il prodotto agisca","Il tempo per far asciugare le mani","La durata del ciclo in autoclave"]'::jsonb, 1, 'Se asciughi prima, il disinfettante non fa effetto: rispetta il tempo indicato in etichetta.'),
  (22, 'igiene', 'Una lima in carta usata su una cliente…', '["Si disinfetta con alcol e si riusa","Si mette in autoclave","Si butta o si regala alla cliente","Si lascia al sole"]'::jsonb, 2, 'È porosa: non si può disinfettare davvero, quindi è monouso.'),
  (23, 'igiene', 'A fine ciclo trovi una busta di sterilizzazione umida. Cosa fai?', '["La usi lo stesso","La asciughi con una salvietta","Consideri la sterilizzazione non riuscita e ripeti il ciclo con busta nuova","La metti nel box UV"]'::jsonb, 2, 'Una busta umida indica un processo incompleto: la busta va rifatta e il ciclo ripetuto.'),
  (24, 'igiene', 'Qual è la protezione più efficace contro la polvere di limatura?', '["La mascherina chirurgica","L''aspirazione vicino alle mani (tavolo aspirante o cappa)","Aprire la porta una volta al giorno","Soffiare via la polvere"]'::jsonb, 1, 'Prima si cattura alla fonte; i DPI sono l''ultima barriera.'),
  (25, 'igiene', 'La DMTA, vietata dal 1° settembre 2025, si trova soprattutto…', '["Negli smalti tradizionali","Nei liquidi per acrilico e negli attivatori dip, come accelerante","Nell''acetone","Nell''olio per cuticole"]'::jsonb, 1, 'La N,N-dimetil-p-toluidina accelera l''indurimento dei sistemi senza lampada: controlla l''INCI di monomeri e attivatori.'),
  (26, 'igiene', 'Ti pungi con una tronchesina appena usata su una cliente. Cosa fai per prima cosa?', '["Ti metti un cerotto e continui","Favorisci il sanguinamento, lavi 10 minuti con acqua e antisettico, disinfetti e consulti un medico","Metti il dito in acetone","Aspetti la fine della giornata"]'::jsonb, 1, 'È la procedura delle linee guida per l''esposizione a sangue: poi serve una valutazione medica.'),
  (27, 'sistemi', 'Il gel monofasico…', '["Non ha bisogno di lampada","Fa da base, costruttore e sigillante","Si usa solo per il french","È un tipo di acrilico"]'::jsonb, 1, 'Un solo prodotto per tutte e tre le fasi.'),
  (28, 'sistemi', 'Come indurisce l''acrilico?', '["In lampada UV","All''aria, per reazione tra liquido e polvere","Con l''acetone","Con l''attivatore spray"]'::jsonb, 1, 'Monomero e polimero reagiscono all''aria.'),
  (29, 'sistemi', 'Una perla di acrilico troppo bagnata…', '["È la più resistente","Cola nei solchi e lascia monomero sulla pelle","È granulosa","Non aderisce"]'::jsonb, 1, 'Troppo liquido = colature, ritiro e rischio allergia.'),
  (30, 'sistemi', 'Il polygel si lavora con…', '["Monomero liquido","Slip solution e pennello, poi lampada","Acqua","Colla per tip"]'::jsonb, 1, 'Si modella con slip solution e indurisce in lampada.'),
  (31, 'sistemi', 'Il semipermanente…', '["Allunga l''unghia","Dà colore per 2–3 settimane ma non struttura","Si toglie solo con la fresa","Non va in lampada"]'::jsonb, 1, 'Colore su unghia naturale, nessuna struttura.'),
  (32, 'sistemi', 'Per scegliere la lampada conta soprattutto…', '["Il numero di watt","Il colore della lampada","L''abbinamento tra lunghezze d''onda e fotoiniziatori del gel","La marca"]'::jsonb, 2, 'Usa la lampada adatta al tuo sistema.'),
  (33, 'sistemi', 'Picco di emissione tipico di una lampada LED per unghie?', '["250 nm","500 nm","Circa 365–405 nm","700 nm"]'::jsonb, 2, 'Le lampade LED per unghie emettono in genere picchi a 365 e/o 405 nm (le fonti indicano 365–405 nm).'),
  (34, 'sistemi', 'Perché un soft gel si toglie con l''acetone e un hard gel no?', '["Perché il soft gel non va in lampada","Perché la rete di polimero del soft gel è meno fitta e l''acetone ci penetra","Perché l''hard gel contiene acetone","Perché il soft gel è un acrilico"]'::jsonb, 1, 'Rete più aperta = l''acetone entra e la scioglie; l''hard gel, molto reticolato, si toglie limando.'),
  (35, 'sistemi', 'Lo strato appiccicoso che resta sul gel dopo la lampada…', '["Indica che la lampada è guasta","È dovuto all''ossigeno dell''aria e si toglie alla fine con cleaner, una salvietta per dito","Va lasciato per sempre","Si toglie con acqua"]'::jsonb, 1, 'È lo strato di dispersione: serve all''aggancio tra gli strati, a fine lavoro si rimuove senza portarlo sulla pelle.'),
  (36, 'sistemi', 'Nella polvere dell''acrilico, cosa fa partire la reazione?', '["L''acetone","Il perossido di benzoile (iniziatore)","Il pigmento","La luce della lampada"]'::jsonb, 1, 'Il BPO nella polvere, attivato dal liquido, avvia la polimerizzazione all''aria.'),
  (37, 'sistemi', 'Perché non conviene usare il liquido di una marca con la polvere di un''altra?', '["Perché cambia il colore","Perché iniziatore e acceleranti sono calibrati tra loro: si rischia un acrilico sotto-polimerizzato o fragile","Perché è vietato dalla legge","Non ci sono problemi"]'::jsonb, 1, 'Più monomero non reagito significa anche più rischio di allergia.'),
  (38, 'sistemi', 'Una lampada da 36 W polimerizza sicuramente meglio di una da 9 W?', '["Sì, sempre","No: conta che emetta le lunghezze d''onda giuste con intensità sufficiente sull''unghia","Sì, se è UV","Dipende solo dal colore"]'::jsonb, 1, 'I watt misurano il consumo elettrico, non la luce utile ai fotoiniziatori.'),
  (39, 'sistemi', 'Nel sistema dip, il modo igienico di applicare la polvere è…', '["Immergere il dito nel barattolo comune","Versare la polvere con un cucchiaino pulito sopra un contenitore monouso e buttare l''avanzo","Soffiare la polvere sull''unghia","Riutilizzare la polvere caduta"]'::jsonb, 1, 'La polvere non si può disinfettare: niente dita nel barattolo comune.'),
  (40, 'attrezzatura', 'Quale grana è la più abrasiva?', '["80","180","240","Buffer"]'::jsonb, 0, 'Numero più basso = grana più grossa.'),
  (41, 'attrezzatura', 'Quale grana usi sull''unghia naturale?', '["80–100","100/180","180–240","Carburo"]'::jsonb, 2, '180–240 per opacizzare senza assottigliare.'),
  (42, 'attrezzatura', 'Le punte in carburo si usano…', '["Sulla cuticola","Solo sul prodotto artificiale","Sull''unghia naturale","Per lucidare"]'::jsonb, 1, 'Sulla lamina naturale e sulla cuticola si usano punte diamantate.'),
  (43, 'attrezzatura', 'Velocità indicativa per lavorare in zona cuticolare?', '["5.000–10.000 RPM","20.000–25.000 RPM","30.000 RPM","Massima"]'::jsonb, 0, 'Velocità basse e pressione leggera vicino alla pelle.'),
  (44, 'attrezzatura', 'Perché la punta della fresa deve restare in movimento?', '["Per lucidare meglio","Per evitare calore da attrito e solchi","Per consumare meno","Non è necessario"]'::jsonb, 1, 'Fermarsi in un punto scalda e scava.'),
  (45, 'attrezzatura', 'Una lima in vetro usata su pelle integra, dopo la cliente…', '["Si butta sempre","Si pulisce e si disinfetta","Si mette in tasca per la prossima cliente","Si lucida con il buffer"]'::jsonb, 1, 'Il vetro non è poroso: pulizia e disinfezione. Le lime in carta invece sono monouso.'),
  (46, 'attrezzatura', 'Che cosa sono gli "anelli di fuoco"?', '["Un effetto di nail art","Solchi circolari sulla lamina causati da una punta della fresa inclinata","Un tipo di lampada","Il segno del primer"]'::jsonb, 1, 'Si evitano tenendo la punta parallela alla superficie e sempre in movimento.'),
  (47, 'attrezzatura', 'Qual è il diametro standard del gambo delle punte professionali per fresa?', '["1/8 di pollice (3,17 mm)","3/32 di pollice (2,35 mm)","5 mm","Non esiste uno standard"]'::jsonb, 1, 'Le punte professionali hanno gambo da 2,35 mm; gli utensili da bricolage non vanno usati sulle clienti.'),
  (48, 'attrezzatura', 'Come si pulisce un pennello da acrilico in setole naturali?', '["In acetone puro ogni sera","Nel monomero, poi asciugato su carta e rimodellato","Con acqua e sapone","Non si pulisce mai"]'::jsonb, 1, 'Acetone e acqua seccano le setole; il monomero le mantiene morbide.'),
  (49, 'attrezzatura', 'Le bande abrasive per fresa (carta su mandrino)…', '["Si sterilizzano in autoclave","Sono monouso","Si lavano in lavatrice","Si usano sulla pelle viva"]'::jsonb, 1, 'Sono porose come le lime in carta: si buttano dopo la cliente.'),
  (50, 'preparazione', 'Qual è la prima causa di sollevamento?', '["La lampada","Una preparazione non accurata","Il colore","La forma"]'::jsonb, 1, 'Pellicine residue (cuticola), polvere, sebo e umidità sono i nemici dell''adesione.'),
  (51, 'preparazione', 'L''opacizzazione dell''unghia naturale serve a…', '["Assottigliarla","Togliere la lucidità","Accorciarla","Sbiancarla"]'::jsonb, 1, 'Si toglie solo la lucidità, mai spessore.'),
  (52, 'preparazione', 'L''ordine corretto è…', '["Primer → disidratante","Disidratante → primer","Solo primer","Top → primer"]'::jsonb, 1, 'Prima si disidrata, poi si applica il primer.'),
  (53, 'preparazione', 'Il primer acido è indicato soprattutto per…', '["Semipermanente","Acrilico e unghie difficili","Top coat","Rimozione"]'::jsonb, 1, 'Va usato in quantità minima e solo sulla lamina.'),
  (54, 'preparazione', 'Dopo il disidratante…', '["Tocco la lamina per controllare","Non tocco più la lamina con le dita","Lavo le mani della cliente","Applico olio"]'::jsonb, 1, 'Il sebo delle dita riduce l''adesione.'),
  (55, 'preparazione', 'Il vero pterigio è…', '["La pellicina morta da togliere sempre","Una condizione anomala in cui la pelle si salda alla lamina: non si tocca","Il bordo libero","Un tipo di primer"]'::jsonb, 1, 'Cuticola e pterigio non sono la stessa cosa: il vero pterigio va indirizzato al medico.'),
  (56, 'preparazione', 'Con quale angolo tieni lo spingicuticole per arretrare l''eponichio?', '["Dritto, a 90° sulla lamina","Quasi piatto, circa 30–45°","Capovolto","Non importa"]'::jsonb, 1, 'Uno strumento dritto graffia la lamina e preme sulla matrice.'),
  (57, 'preparazione', 'Quale grana NON si usa mai sulla lamina naturale?', '["240","180","100","Buffer fine"]'::jsonb, 2, 'Le grane 80–100 servono solo per il prodotto artificiale.'),
  (58, 'preparazione', 'Come deve essere il pennello del primer prima di applicarlo?', '["Ben carico","Quasi asciutto","Bagnato di acetone","Pulito con olio"]'::jsonb, 1, 'L''eccesso di primer riduce l''adesione e rischia di toccare la pelle.'),
  (59, 'preparazione', 'Il primer senza acido si applica…', '["Su lamina e tip","Solo sulla lamina naturale, ad almeno 1 mm dalla pelle","Sulla pelle intorno per proteggerla","Dopo la base"]'::jsonb, 1, 'Mai su tip e pelle; poi si parte con base o prodotto.'),
  (60, 'preparazione', 'Il primer acido è pronto per il prodotto quando…', '["È ancora bagnato e lucido","È asciutto e appare bianco gessoso","Dopo un giorno","Dopo il top"]'::jsonb, 1, 'Si lavora sul primer acido asciutto.'),
  (61, 'tip', 'Come scegli la misura del tip?', '["Il più piccolo possibile","Deve coprire da solco a solco","Sempre la misura 5","In base al colore"]'::jsonb, 1, 'Se sei tra due misure scegli la più grande e lima i lati.'),
  (62, 'tip', 'Con quale angolo si appoggia il tip?', '["90°","Circa 45°, poi si abbassa","0°, piatto subito","180°"]'::jsonb, 1, 'Abbassandolo lentamente l''aria esce e non si formano bolle.'),
  (63, 'tip', 'Durante il blending del tip…', '["Limo anche l''unghia naturale","Fondo solo la linea di contatto del tip","Uso la grana 80 sulla lamina","Uso acetone"]'::jsonb, 1, 'Non si lima l''unghia naturale.'),
  (64, 'tip', 'I tip "a contatto"…', '["Hanno un incavo da fondere","Non hanno incavo e non vanno fusi","Si applicano senza colla","Sono solo per i piedi"]'::jsonb, 1, 'Non c''è zona d''incavo da fondere.'),
  (65, 'tip', 'Quanto può coprire al massimo l''incavo del tip?', '["Tutta la lamina fino alla cuticola","Circa metà della lamina","Solo 1 mm","Non importa"]'::jsonb, 1, 'Se l''incavo è più lungo si accorcia prima di incollare.'),
  (66, 'tip', 'Per quanto tempo tieni premuto il tip dopo averlo abbassato?', '["Non serve tenerlo","Circa 5–10 secondi, fermo","2 minuti","Finché la cliente sente caldo"]'::jsonb, 1, 'Muoverlo mentre la colla indurisce indebolisce il legame.'),
  (67, 'tip', 'Quando si taglia il tip?', '["Prima di incollarlo, sempre","Quando la colla è indurita","Mentre la colla è ancora liquida","Dopo il top"]'::jsonb, 1, 'A colla fresca il tip si sposta e il legame si rompe.'),
  (68, 'tip', 'Come tieni la lima durante la fusione?', '["Di taglio, premendo","Piatta, solo sulla plastica, in movimento","Ferma su un punto","Sulla pelle"]'::jsonb, 1, 'Ferma o di taglio crea solchi; sulla lamina la assottiglia.'),
  (69, 'tip', 'Dove applichi il primer in una ricostruzione su tip?', '["Su tutto il tip","Solo sulla lamina naturale","Sulla pelle","Non si usa mai"]'::jsonb, 1, 'Sul tip non serve e può rovinare la plastica.'),
  (70, 'tip', 'Che cosa indica una macchia chiara sotto l''incavo dopo l''incollaggio?', '["Una bolla d''aria: il tip va riapplicato","Che la colla è perfetta","Una micosi","Il punto di stress"]'::jsonb, 0, 'Una bolla diventa un sollevamento.'),
  (71, 'cartina', 'Dove va costruito l''apex?', '["Alla cuticola","Sopra il punto di stress","Sulla punta","Ovunque"]'::jsonb, 1, 'In zona 2, sopra il punto di stress.'),
  (72, 'cartina', 'Quanto margine lasci dalla pelle in zona cuticolare?', '["Nessuno","Circa 1 mm","5 mm","1 cm"]'::jsonb, 1, 'Circa 1 mm (le fonti indicano 0,5–1,5 mm): il prodotto non deve mai toccare la pelle.'),
  (73, 'cartina', 'Cosa succede se la cartina lascia uno spazio sotto il bordo libero?', '["Niente","Il prodotto cola sotto e crea sollevamenti","L''unghia è più robusta","Si polimerizza prima"]'::jsonb, 1, 'La cartina va a filo del bordo libero.'),
  (74, 'cartina', 'Una ricostruzione piatta, senza apex…', '["È più naturale e resistente","Si rompe facilmente","Non si solleva mai","Dura di più"]'::jsonb, 1, 'Senza struttura non regge la lunghezza.'),
  (75, 'cartina', 'Quando si pizzica il gel per la curva a C?', '["Prima di stenderlo","Dopo una breve polimerizzazione (flash cure)","Dopo il top","Mai"]'::jsonb, 1, 'Per l''acrilico invece mentre non è del tutto indurito.'),
  (76, 'cartina', 'La zona 3 deve essere…', '["La più spessa","Sottilissima","Bianca","Lucida"]'::jsonb, 1, 'Sottile in zona cuticolare, struttura in zona 2.'),
  (77, 'cartina', 'Di profilo, la cartina corretta…', '["È inclinata verso il basso","Prosegue in linea la lamina naturale","È inclinata verso l''alto","È verticale"]'::jsonb, 1, 'Verso il basso l''allungamento cade, verso l''alto si ottiene uno ski-jump.'),
  (78, 'cartina', 'Le alette della cartina si fissano…', '["Avvolgendo tutta la nocca","Unendole sotto il polpastrello e sui lati del dito","Sopra l''unghia","Non si fissano"]'::jsonb, 1, 'Sulla nocca si staccano quando il dito si piega.'),
  (79, 'cartina', 'Una cliente con iponichio lungo sente dolore con la cartina. Cosa fai?', '["Spingo di più","Ritaglio un incavo più profondo nel punto di contatto","Continuo comunque","Uso un primer acido"]'::jsonb, 1, 'La cartina deve toccare il bordo libero senza premere sulla pelle viva.'),
  (80, 'cartina', 'Quanto è spesso, indicativamente, il bordo libero finito?', '["Come un foglio di carta","Circa 1–1,5 mm, come una carta di credito","5 mm","Non conta"]'::jsonb, 1, 'Più spesso si impiglia, più sottile si scheggia.'),
  (81, 'cartina', 'Una perla di acrilico media ha un rapporto liquido/polvere di circa…', '["1 : 1","1,5 : 1","3 : 1","1 : 3"]'::jsonb, 1, '1 : 1 è asciutta, 2 : 1 bagnata; il valore esatto dipende dal sistema.'),
  (82, 'cartina', 'Per un risultato equilibrato il bordo libero non dovrebbe superare circa…', '["Il doppio del letto ungueale","Metà della lunghezza del letto ungueale","1 mm","La lunghezza del dito"]'::jsonb, 1, 'Più lunghezza significa più leva sul punto di stress.'),
  (83, 'limatura', 'Quale forma è considerata tra le più resistenti?', '["Stiletto","Squoval","Lipstick","Ballerina"]'::jsonb, 1, 'Gli angoli smussati riducono il rischio di rotture.'),
  (84, 'limatura', 'Quale forma slancia di più il dito?', '["Quadrata","Mandorla","Tonda","Squoval"]'::jsonb, 1, 'I lati convergenti allungano visivamente il dito.'),
  (85, 'limatura', 'Come si limano i lati?', '["Con la lima parallela al solco laterale","Entrando nel solco","Con la grana 80","In diagonale"]'::jsonb, 0, 'Senza entrare nel solco.'),
  (86, 'limatura', 'Il movimento corretto della lima è…', '["Avanti e indietro veloce","In una sola direzione","Circolare con forza","Casuale"]'::jsonb, 1, 'Il movimento a "sega" scalda e sfibra.'),
  (87, 'limatura', 'Da quanti punti di vista controlli la ricostruzione?', '["Solo dall''alto","Alto, profilo, fronte e sotto","Solo di profilo","Non serve controllare"]'::jsonb, 1, 'Simmetria, apex, curva a C e pulizia del bordo.'),
  (88, 'limatura', 'In quale ordine si lima una ricostruzione?', '["Superficie, punta, lunghezza, lati","Lunghezza, lati, punta, superficie, sotto il bordo","Solo superficie","Punta, cuticola, lunghezza"]'::jsonb, 1, 'La forma si decide sulla lunghezza finale; la superficie si rifinisce dopo.'),
  (89, 'limatura', 'Da dove si parte per ottenere quasi tutte le forme?', '["Da una stiletto","Da una base quadrata con lati paralleli","Da una forma tonda","Dalla lipstick"]'::jsonb, 1, 'Togliendo gli angoli in modo diverso si arriva alle altre forme.'),
  (90, 'limatura', 'Come si tiene il dito della cliente durante la limatura?', '["Con un dito appoggiato sull''unghia","Ai lati della prima falange, senza toccare la superficie","Per la punta dell''unghia","Non si tiene"]'::jsonb, 1, 'Toccare la superficie lascia sebo e impedisce di vedere.'),
  (91, 'limatura', 'Per la ballerina (coffin)…', '["I lati si allargano verso la punta","I lati si restringono e la punta è dritta","La punta è tonda","È una quadrata corta"]'::jsonb, 1, 'Si restringe come una stiletto ma ci si ferma prima e si taglia la punta dritta.'),
  (92, 'limatura', 'Perché si segna un puntino al centro della punta prima di limare?', '["Per decorare","Come riferimento per la simmetria","Per il primer","Per misurare la grana"]'::jsonb, 1, 'La punta deve cadere sull''asse del dito.'),
  (93, 'limatura', 'Il top può correggere piccoli difetti di limatura?', '["Sì, li nasconde","No: il top lucido li mette in risalto","Solo sui lati","Solo con due strati"]'::jsonb, 1, 'Si corregge con la lima prima del top.'),
  (94, 'decorazioni', 'Una buona smile line è…', '["Asimmetrica","Simmetrica, netta e con la stessa profondità sui lati","Piatta","Sfumata"]'::jsonb, 1, 'Simmetria e nettezza sono i criteri principali, e la smile deve essere uguale su tutte le dita.'),
  (95, 'decorazioni', 'Una smile line troppo piatta…', '["Allunga visivamente il letto","Fa sembrare l''unghia più larga e corta","Non cambia nulla","Rende il bianco più coprente"]'::jsonb, 1, 'La profondità della curva cambia la percezione: piatta allarga, troppo profonda sembra innaturale.'),
  (96, 'decorazioni', 'Quale curva di smile line è in genere più armoniosa?', '["Una linea dritta","Una curva che ripete quella della cuticola","Una curva diversa per ogni dito","Una curva che segue sempre il bordo libero naturale"]'::jsonb, 1, 'La smile che "fa eco" alla cuticola è proporzionata; inoltre può stare più in alto del bordo naturale per allungare il letto.'),
  (97, 'decorazioni', 'Perché il gel bianco si stende in strati sottili?', '["Per risparmiare prodotto","Perché i pigmenti schermano la luce e uno strato spesso resta morbido sotto","Perché il bianco non si polimerizza mai","Per renderlo trasparente"]'::jsonb, 1, 'È l''effetto ombrello dei pigmenti: meglio due strati sottili ben polimerizzati.'),
  (98, 'decorazioni', 'Nel reverse french l''arco di colore si disegna…', '["Sul bordo libero","Alla base, dal centro verso i lati, lasciando circa 1 mm dalla pelle","Toccando la cuticola per coprirla","Solo con lo stamping"]'::jsonb, 1, 'Partire dal centro aiuta la regolarità; il margine evita sollevamenti e contatto con la pelle.'),
  (99, 'decorazioni', 'Il baby boomer è…', '["Un french con linea netta","Una sfumatura dal nude al bianco","Un tipo di gel","Una forma"]'::jsonb, 1, 'È un french sfumato, senza linea netta.'),
  (100, 'decorazioni', 'Nel baby boomer la sfumatura si ottiene soprattutto…', '["Limando forte la zona di passaggio","Con il pennello, a colpi brevi e strati sottili","Con un solo strato spesso di bianco","Con il top coat"]'::jsonb, 1, 'La lima assottiglia la zona sfumata e crea macchie; la sfumatura si costruisce con il pennello.'),
  (101, 'decorazioni', 'L''incapsulato consiste nel…', '["Chiudere decorazioni tra due strati trasparenti","Mettere glitter sul top","Usare solo colori","Dipingere con il dotter"]'::jsonb, 0, 'Le decorazioni restano protette dentro il prodotto, con l''apex costruito sopra.'),
  (102, 'decorazioni', 'Lo stamping usa…', '["Una piastra incisa e un tampone","Una fresa","Un attivatore","Solo pennelli"]'::jsonb, 0, 'Il disegno viene trasferito dalla piastra all''unghia con il tampone.'),
  (103, 'decorazioni', 'Nello stamping il raschietto si passa…', '["In verticale premendo forte","A circa 45° per lasciare lo smalto solo nelle incisioni","Dopo il tampone","Solo se lo smalto è già secco"]'::jsonb, 1, 'Poi si rotola subito il tampone sul disegno e sull''unghia.'),
  (104, 'manutenzione', 'Ogni quanto si consiglia il refill di una ricostruzione?', '["Ogni settimana","Ogni 3–4 settimane","Ogni 3 mesi","Mai"]'::jsonb, 1, 'Dopo 3–4 settimane l''apex si è spostato in avanti; il semipermanente si rifà in genere ogni 2–3 settimane.'),
  (105, 'manutenzione', 'Di quanto cresce in media un''unghia della mano in un mese?', '["Circa 0,5 mm","Circa 3–3,5 mm","Circa 1 cm","Circa 2 cm"]'::jsonb, 1, 'In uno studio su giovani adulti la media era 3,47 mm al mese: poco meno di 1 mm a settimana.'),
  (106, 'manutenzione', 'Durante il refill le parti sollevate…', '["Si coprono con prodotto nuovo","Si eliminano completamente","Si incollano","Si lasciano"]'::jsonb, 1, 'Sotto un sollevamento possono esserci umidità e batteri.'),
  (107, 'manutenzione', 'Come si elimina un sollevamento durante il refill?', '["Si taglia con la tronchesina","Si lima fino al punto in cui il prodotto è ben attaccato","Si incolla","Si copre con prodotto nuovo"]'::jsonb, 1, 'Tagliare o strappare porta via strati di lamina e crea nuovi sollevamenti.'),
  (108, 'manutenzione', 'Durante il rebalance il vecchio prodotto si assottiglia indicativamente…', '["Per niente","Del 30–50%, in base alla ricrescita","Fino all''unghia naturale","Solo sul bordo libero"]'::jsonb, 1, 'Così si può ricostruire l''apex nel punto giusto senza rendere l''unghia sempre più spessa.'),
  (109, 'manutenzione', 'Una cliente ha una crepa nel prodotto: cosa le consigli fino all''appuntamento?', '["Incollarla con colla per tip","Coprirla con un cerotto","Non incollare né coprire, limare via la parte che si aggancia e prenotare la riparazione","Strappare il prodotto"]'::jsonb, 2, 'Colla e cerotto chiudono umidità e batteri sotto il prodotto.'),
  (110, 'manutenzione', 'Quanto tempo serve in genere per il soak-off del semipermanente?', '["1 minuto","10–15 minuti","2 ore","24 ore"]'::jsonb, 1, 'Per soft gel spessi si arriva a circa 30 minuti; l''acrilico richiede in genere 20–30 minuti.'),
  (111, 'manutenzione', 'Quale tempo in acetone è più realistico per un acrilico già assottigliato?', '["1–2 minuti","20–30 minuti","2 ore","Non si scioglie"]'::jsonb, 1, 'Il semipermanente richiede meno tempo (circa 10–15 min); l''hard gel invece non si scioglie e si lima.'),
  (112, 'manutenzione', 'L''hard gel si rimuove…', '["Con acetone","Limando, lasciando un velo sulla lamina","Strappandolo","Con acqua calda"]'::jsonb, 1, 'Non si scioglie in acetone.'),
  (113, 'manutenzione', 'La lamina biancastra subito dopo un soak-off è di solito…', '["Un danno permanente","Disidratazione superficiale temporanea","Una micosi","Prodotto rimasto"]'::jsonb, 1, 'Si recupera in alcune ore; i danni veri vengono dal raschiare o dal fare leva.'),
  (114, 'manutenzione', 'Dopo la rimozione…', '["Si gratta la lamina","Si applica olio per cuticole","Si mette subito un nuovo gel senza preparare","Si lima con grana 80"]'::jsonb, 1, 'Nutrire la zona aiuta la pelle e la lamina.'),
  (115, 'problemi', 'Quale NON è una causa di sollevamento?', '["Cuticola non rimossa dalla lamina","Prodotto a contatto con la pelle","Bordo libero sigillato","Refill in ritardo"]'::jsonb, 2, 'Sigillare il bordo libero previene il sollevamento.'),
  (116, 'problemi', 'Un sollevamento al centro dell''unghia ("a tasca") fa pensare soprattutto a…', '["Bordo libero non sigillato","Adesione scarsa, perla sbagliata o una botta","Prodotto sui solchi laterali","Lampada troppo lenta"]'::jsonb, 1, 'Il centro non è vicino alla pelle: le cause tipiche sono adesione, rapporto liquido/polvere e traumi.'),
  (117, 'problemi', 'Quanto margine si lascia indicativamente tra prodotto e pelle?', '["Nessuno","Circa 1 mm","Circa 3 mm","Metà unghia"]'::jsonb, 1, 'Le fonti indicano 0,5–1,5 mm: il prodotto sulla pelle non aderisce, fa leva e aumenta il rischio di allergia.'),
  (118, 'problemi', 'Il sollevamento compare su tutte le dita di una cliente dopo pochi giorni. Prima cosa da controllare?', '["Le abitudini della cliente","La tua preparazione e applicazione","Il colore scelto","La forma"]'::jsonb, 1, 'Tutte le dita + subito = protocollo, prodotto o lampada.'),
  (119, 'problemi', 'Una rottura in zona 2 dipende spesso da…', '["Apex assente o mal posizionato","Troppo olio","Colore scuro","Top lucido"]'::jsonb, 0, 'La struttura deve reggere il punto di stress.'),
  (120, 'problemi', 'Il picco di calore è favorito da…', '["Strati sottili","Strati spessi e lamina assottigliata","Gel a basso calore","Lampada in low-heat"]'::jsonb, 1, 'La polimerizzazione è esotermica: strati spessi = più calore.'),
  (121, 'problemi', 'Perché un gel non abbinato alla lampada può scottare di più?', '["Perché la lampada è spenta","Perché libera lo stesso calore in molto meno tempo","Perché il gel diventa più spesso","Non scotta mai"]'::jsonb, 1, 'Una lampada molto veloce concentra la reazione: il calore arriva tutto insieme.'),
  (122, 'problemi', 'La tecnica "flash and pull" serve a…', '["Accelerare la polimerizzazione","Ridurre il calore percepito","Rimuovere il gel","Lucidare"]'::jsonb, 1, 'Si toglie la mano dalla lampada qualche secondo e la si rimette.'),
  (123, 'problemi', 'Le grinze sul gel indicano di solito…', '["Strato troppo spesso polimerizzato solo in superficie","Troppo primer","Lima sbagliata","Smile line storta"]'::jsonb, 0, 'Strati sottili e tempi corretti risolvono il problema.'),
  (124, 'problemi', 'Un colore scuro steso spesso fa le grinze perché…', '["È scaduto","I pigmenti fanno ombra e la luce non arriva negli strati sotto","Il top è opaco","L''unghia è troppo corta"]'::jsonb, 1, 'Si forma una pelle dura sopra il gel liquido: la soluzione sono strati sottili.'),
  (125, 'problemi', 'Un gel sotto-polimerizzato aumenta il rischio di…', '["Ingiallimento soltanto","Allergia","Unghie più dure","Nessun problema"]'::jsonb, 1, 'Il monomero non reagito sensibilizza la pelle.'),
  (126, 'problemi', 'Una cliente ha prurito e rossore intorno alle unghie dopo il servizio. Cosa fai?', '["Aggiungi un altro strato","Interrompi, rimuovi con delicatezza e consigli il medico","Le dai una crema e continui","Aspetti il refill"]'::jsonb, 1, 'Può essere una dermatite allergica da contatto: annotala sulla scheda e rivedi la tecnica.'),
  (127, 'professione', 'Cosa NON serve nella scheda cliente?', '["Allergie","Farmaci e patologie","Il colore preferito dell''auto","Consenso privacy"]'::jsonb, 2, 'La scheda raccoglie dati utili alla sicurezza del servizio.'),
  (128, 'professione', 'Allergie, farmaci e gravidanza scritti nella scheda cliente sono…', '["Dati qualunque","Dati relativi alla salute, protetti in modo particolare dal GDPR","Dati pubblici","Dati fiscali"]'::jsonb, 1, 'Sono "categorie particolari" (art. 9 GDPR): servono informativa, consenso esplicito e custodia sicura.'),
  (129, 'professione', 'Per pubblicare sui social la foto delle mani di una cliente serve…', '["Niente, se le unghie le ho fatte io","Un consenso separato e specifico, che la cliente può rifiutare","Solo la firma sulla scheda del servizio","Il permesso del Comune"]'::jsonb, 1, 'La foto non è necessaria al servizio: serve un consenso a parte. Garante e Cassazione si sono espressi su casi simili.'),
  (130, 'professione', 'Quale consiglio dai dopo il trattamento?', '["Usare le unghie per aprire le lattine","Olio per cuticole ogni giorno e guanti per i lavori domestici","Staccare da sola il prodotto","Saltare il refill"]'::jsonb, 1, 'Cura quotidiana e protezione allungano la durata.'),
  (131, 'professione', 'Quale foto mostra meglio la posizione dell''apex?', '["Dall''alto","Di profilo","Da lontano con la cliente in posa","Con un filtro colorato"]'::jsonb, 1, 'Dall''alto si vedono forma e smile line; a tunnel la curva a C; di profilo apex e spessore.'),
  (132, 'professione', 'Prezzo indicativo di un refill in Italia?', '["5 €","25–35 €","150 €","300 €"]'::jsonb, 1, 'Ordine di grandezza da articoli e testimonianze 2021–2025; i prezzi variano molto per zona e centro.'),
  (133, 'professione', 'Come si calcola il costo dei materiali per servizio?', '["Prezzo del gel diviso per 10","Spesa mensile per i prodotti divisa per il numero di clienti del mese","Si copia il prezzo della concorrenza","Non serve calcolarlo"]'::jsonb, 1, 'Meglio fare la media su più mesi per tener conto dei periodi più o meno pieni.'),
  (134, 'professione', 'Nel regime forfettario, su cosa si calcolano imposta e contributi di un''estetista?', '["Su tutti gli incassi","Sul 67% degli incassi (coefficiente di redditività)","Solo sugli incassi in contanti","Sul guadagno dopo aver tolto le spese reali"]'::jsonb, 1, 'Le spese reali non si scaricano: sono comprese forfettariamente nel 33% non tassato.'),
  (135, 'professione', 'I contributi INPS fissi degli artigiani…', '["Si pagano solo se si guadagna più di 85.000 €","Si pagano sul minimale anche se si guadagna meno","Non esistono in forfettario","Si pagano una volta sola all''apertura"]'::jsonb, 1, 'Nel 2026 il minimale è 18.808 € e i contributi fissi circa 4.521 € l''anno; i forfettari possono chiedere la riduzione del 35%.'),
  (136, 'professione', 'Nelle gare i giudici valutano soprattutto…', '["Il prezzo","Struttura, simmetria, pulizia e smile line","La marca dei prodotti","La velocità di pagamento"]'::jsonb, 1, 'Apex, curva a C, simmetria e pulizia sono decisivi.'),
  (137, 'onicofagia', 'Quale situazione è una controindicazione su unghie rosicchiate?', '["Unghie corte","Presenza di pus e gonfiore","Cuticole secche","Lamina sottile"]'::jsonb, 1, 'Infezione o infiammazione richiedono il medico, non una ricostruzione.'),
  (138, 'onicofagia', 'Perché si tira la cartina verso il basso su un''unghia rosicchiata?', '["Per risparmiare prodotto","Per spingere indietro la pelle rialzata e fare spazio all''allungamento","Per accorciare il letto","Per evitare il top"]'::jsonb, 1, 'Crea spazio per l''allungamento davanti all''unghia.'),
  (139, 'onicofagia', 'La causa più frequente della coilonichia (unghia a cucchiaio) è:', '["Carenza di ferro","Trauma da lima","Smalto scuro","Acetone"]'::jsonb, 0, 'Se compare da poco, si consiglia un controllo medico.'),
  (140, 'onicofagia', 'Con un''unghia ski-jump, cosa si fa prima di applicare il tip?', '["Si allunga di più","Si riduce la lunghezza naturale","Si lucida","Si applica il top"]'::jsonb, 1, 'Altrimenti il tip segue la curva verso l''alto.'),
  (141, 'onicofagia', 'Su un''unghia a pinza dolorante l''onicotecnica:', '["Accentua la curva C","Fa il pinching","Indirizza a medico o podologo","Applica acrilico spesso"]'::jsonb, 2, 'La deformità comprime i tessuti: non si forza.'),
  (142, 'onicofagia', 'Su unghie grasse il ritiro del gel è legato soprattutto a:', '["Lampada nuova","Olio residuo sulla lamina","Colori chiari","Cartine di carta"]'::jsonb, 1, 'Disidratante, primer adatto e nuovo sgrassaggio prima della base.'),
  (143, 'onicofagia', 'Secondo una regola usata dai formatori, quanto dovrebbe essere lungo al massimo l''allungamento su un''unghia rosicchiata?', '["Il doppio del letto","Circa 1/3 della lunghezza della lamina","Uguale al letto","Non conta la lunghezza"]'::jsonb, 1, 'Una leva lunga su un''unghia piccola causa rotture e sollevamenti; si allunga poco alla volta.'),
  (144, 'onicofagia', 'Perché si taglia una piccola "U" nella cartina su un''unghia rosicchiata?', '["Per risparmiare carta","Per non premere sull''iponichio rialzato","Per fare la smile line","Per far colare il gel"]'::jsonb, 1, 'Il cuscinetto di pelle è vivo: la U evita pressione e dolore.'),
  (145, 'onicofagia', 'Su un''unghia rosicchiata resta uno spazio tra lamina e cartina. Cosa succede?', '["Niente","Il prodotto cola sotto e crea uno scalino debole e \"mordibile\"","Il gel polimerizza più in fretta","La curva C migliora"]'::jsonb, 1, 'La cartina deve essere a filo del bordo, anche se il bordo quasi non c''è.'),
  (146, 'onicofagia', 'Perché nelle prime settimane gli appuntamenti sono più ravvicinati?', '["Per vendere di più","Le ricostruzioni su unghie molto rosicchiate durano meno e vanno controllate spesso","Perché il gel scade","Non serve"]'::jsonb, 1, 'Superficie di appoggio piccola e abitudine ancora presente: controlli frequenti, poi refill normali.'),
  (147, 'onicofagia', 'Un''unghia mostra una banda scura longitudinale comparsa da poco. Cosa fai?', '["La copri con il cover","La limi","Consigli una visita dal medico","La ignori"]'::jsonb, 2, 'Una banda scura nuova va sempre valutata dal medico: non spetta all''onicotecnica dire da cosa dipende.'),
  (148, 'onicofagia', 'Con un''unghia a cucchiaio, la cartina si posiziona:', '["Seguendo la conca","In asse con il dito, dopo aver livellato la conca","Verso l''alto","Non si usa la cartina"]'::jsonb, 1, 'Seguire la conca farebbe puntare l''allungamento verso l''alto.'),
  (149, 'cover-colori', 'A cosa serve principalmente il gel cover?', '["Lucidare","Allungare otticamente il letto ungueale e coprire imperfezioni","Sgrassare","Ammorbidire le cuticole"]'::jsonb, 1, 'È un costruttore pigmentato color pelle.'),
  (150, 'cover-colori', 'Perché i gel molto pigmentati vanno stesi sottili?', '["Per risparmiare","Perché il pigmento assorbe la luce e gli strati profondi polimerizzano male","Per un effetto opaco","Non serve"]'::jsonb, 1, 'Con strati spessi la parte profonda resta sotto-polimerizzata.'),
  (151, 'cover-colori', 'Il primo strato di un colore appare striato. È:', '["Un difetto del prodotto","Normale: il secondo strato uniforma","Segno di lampada rotta","Da rimuovere sempre"]'::jsonb, 1, 'Molti colori coprono al secondo strato sottile.'),
  (152, 'cover-colori', 'Quale NON è una causa di ritiro dai bordi?', '["Olio sulla lamina","Primer ancora umido sui lati","Lampada non compatibile","Uso di una cartina di carta"]'::jsonb, 3, 'Le prime tre sono cause tipiche di ritiro.'),
  (153, 'cover-colori', 'Il colore complementare del giallo, che lo neutralizza, è:', '["Viola","Verde","Arancio","Rosso"]'::jsonb, 0, 'Sono opposti sul cerchio cromatico.'),
  (154, 'cover-colori', 'Per un french con camouflage, la sequenza consigliata è:', '["Bianco prima, cover dopo","Cover prima, poi la smile line","Solo top","Solo bianco"]'::jsonb, 1, 'Si disegna la smile line sopra il cover.'),
  (155, 'cover-colori', 'Perché, in un french su letto allungato, si abbassano leggermente gli angoli della smile line?', '["Per risparmiare bianco","Per non lasciare zone trasparenti ai lati dove non c''è cover","Per allungare il bordo","Non si abbassano mai"]'::jsonb, 1, 'Se gli angoli salgono troppo, sotto il bianco restano piccole "orecchie" trasparenti.'),
  (156, 'cover-colori', 'Quali pigmenti assorbono più luce UV e sono più difficili da polimerizzare?', '["Bianco e blu","Rossi e neri","Solo i glitter","Tutti uguali"]'::jsonb, 1, 'Rossi e neri assorbono di più: strati sottili e tempi da scheda tecnica.'),
  (157, 'cover-colori', 'Uno strato di colore molto spesso si raggrinzisce dopo la lampada. Perché?', '["La lampada è troppo nuova","La superficie indurisce ma sotto il gel resta morbido","Il colore è scaduto","Manca il top"]'::jsonb, 1, 'La luce non arriva in fondo; un tempo più lungo non risolve uno strato troppo spesso.'),
  (158, 'cover-colori', 'Dove si sceglie il colore del cover?', '["Sotto la lampada UV","Alla luce naturale, appoggiando il tip sull''unghia","Al buio","Solo dal catalogo"]'::jsonb, 1, 'La luce naturale mostra il colore com''è; si confronta con il letto ungueale.'),
  (159, 'cover-colori', 'Perché si "sigilla" il bordo libero passando il colore sullo spessore della punta?', '["Per decorare","Per ridurre ritiro e scheggiature in punta","Per accelerare la lampada","Non serve"]'::jsonb, 1, 'Il colore avvolge il bordo e non si ritira.'),
  (160, 'cover-colori', 'Sotto uno smalto rosso o arancio, i dermatologi consigliano:', '["Nessuna base","Uno strato in più di base per evitare l''ingiallimento","Il top prima del colore","Acetone"]'::jsonb, 1, 'Indicazione dell''American Academy of Dermatology.'),
  (161, 'piedi', 'Rispetto alle mani, le unghie dei piedi crescono:', '["Più velocemente","Alla stessa velocità","A meno della metà della velocità","Non crescono"]'::jsonb, 2, 'Circa 1,6 contro 3,5 mm al mese in uno studio su giovani adulti.'),
  (162, 'piedi', 'Per prevenire l''unghia incarnita si taglia:', '["A punta","Molto corta e tonda","Dritta, angoli appena smussati","Scavando i lati"]'::jsonb, 2, 'Indicazione dei dermatologi (AAD).'),
  (163, 'piedi', 'Un''unghia gialla, ispessita e friabile:', '["Si copre con gel colorato","Si lima fino ad assottigliarla","Non si tratta: si consiglia medico o podologo","Si ricostruisce in acrilico"]'::jsonb, 2, 'Possibile micosi: controindicazione.'),
  (164, 'piedi', 'Chi tratta le unghie incarnite in Italia?', '["L''estetista","L''onicotecnica","Il podologo (o il medico)","Chiunque abbia una lima"]'::jsonb, 2, 'Il podologo è una professione sanitaria (DM 666/1994).'),
  (165, 'piedi', 'Cliente diabetica con una ferita al piede che non guarisce:', '["Pedicure con lama","Pediluvio caldo","Niente servizio, invio a medico o podologo","Semipermanente rinforzato"]'::jsonb, 2, 'Rischio di lesioni non percepite e infezioni.'),
  (166, 'piedi', 'La L. 1/1990 esclude dall''attività di estetista:', '["La manicure estetica","Le prestazioni con finalità terapeutica","Il trucco","Il massaggio estetico"]'::jsonb, 1, 'L''estetista lavora a scopo estetico.'),
  (167, 'piedi', 'Dopo ogni cliente, la vaschetta del pediluvio va:', '["Solo risciacquata","Svuotata, pulita con sapone, disinfettata per il tempo di contatto indicato, asciugata e registrata","Riempita con acqua calda","Spruzzata con profumo"]'::jsonb, 1, 'Senza pulizia il disinfettante funziona male; il tempo di contatto (es. 10 minuti in California) va rispettato.'),
  (168, 'piedi', 'Che consiglio si dà alla cliente prima di una pedicure?', '["Radersi le gambe la mattina stessa","Non radersi le gambe nelle 24 ore prima","Mettere crema grassa sulle unghie","Venire con lo smalto vecchio"]'::jsonb, 1, 'I microtagli del rasoio sono porte d''ingresso per i germi.'),
  (169, 'piedi', 'Quanto tempo può servire perché un''unghia dell''alluce si rinnovi del tutto?', '["2 settimane","1 mese","Fino a 12–18 mesi","10 anni"]'::jsonb, 2, 'Le unghie dei piedi crescono circa 1,6 mm al mese.'),
  (170, 'piedi', 'Con una cliente diabetica, la temperatura dell''acqua si controlla:', '["Chiedendo alla cliente","Con il termometro o con il proprio gomito","Con la punta del piede della cliente","Non serve controllarla"]'::jsonb, 1, 'Con la neuropatia la cliente può non sentire il calore e scottarsi.'),
  (171, 'piedi', 'Secondo il DM 666/1994, le callosità sono trattate da:', '["Estetista con lama","Podologo","Onicotecnica","Nessuno"]'::jsonb, 1, 'Il podologo tratta con metodi incruenti callosità, unghie ipertrofiche, deformi e incarnite.'),
  (172, 'piedi', 'Perché i pediluvi con tubature di ricircolo sono considerati più a rischio?', '["Consumano più acqua","Nelle tubature possono crescere micobatteri difficili da eliminare","Sono più rumorosi","Non sono più a rischio"]'::jsonb, 1, 'Indagine CDC in California: micobatteri in 29 vasche su 30.'),
  (173, 'arte-gare', 'Su cosa si applica la polvere chrome?', '["Gel colorato non polimerizzato","Top no-wipe polimerizzato","Base appiccicosa","Lamina nuda"]'::jsonb, 1, 'Poi si sigillano i bordi e si mette il top.'),
  (174, 'arte-gare', 'Nel cat-eye il magnete si usa:', '["Dopo il top","Prima di polimerizzare lo strato magnetico","Dopo la polimerizzazione","Non serve"]'::jsonb, 1, 'Le particelle si orientano finché il gel è fluido.'),
  (175, 'arte-gare', 'Nel one-stroke, per iniziare, il pennello piatto si carica:', '["Con un solo colore","Circa metà e metà con due colori","Fino alla ghiera","Asciutto"]'::jsonb, 1, 'Il colore non deve entrare nella ghiera.'),
  (176, 'arte-gare', 'In gara, il gel non polimerizzato a fine prova comporta:', '["−5 punti","Nessuna penalità","Squalifica","Un bonus"]'::jsonb, 2, 'È una regola tipica dei regolamenti Nailympia.'),
  (177, 'arte-gare', 'La "vista a tunnel" valuta soprattutto:', '["La smile line","La curva C","Il colore","La lucentezza"]'::jsonb, 1, 'Si guarda l''unghia dalla punta.'),
  (178, 'arte-gare', 'In un''unghia con decorazione incapsulata, l''apex:', '["Non serve","Si costruisce sopra la decorazione","Va alla cuticola","Si sostituisce con glitter"]'::jsonb, 1, 'La struttura deve restare corretta.'),
  (179, 'arte-gare', 'Prima del top finale sul chrome, perché si passa un buffer leggero sul bordo libero?', '["Per accorciare l''unghia","Per togliere la polvere libera che impedirebbe al top di aderire","Per opacizzare il chrome","Non si fa mai"]'::jsonb, 1, 'La polvere libera sulla punta fa staccare il top.'),
  (180, 'arte-gare', 'Il gel per foil "non tiene" il foil. Causa probabile?', '["Strato troppo spesso o non polimerizzato abbastanza","Lampada troppo nuova","Foil troppo lucido","Colore sotto troppo chiaro"]'::jsonb, 0, 'Serve un velo sottile, polimerizzato fino a restare appiccicoso.'),
  (181, 'arte-gare', 'Dove conviene incapsulare una decorazione?', '["Alla cuticola","Sui lati","Nelle zone spesse: smile line, apex, centro della punta","Sul bordo libero"]'::jsonb, 2, 'Le zone sottili costringono a lasciare un rigonfiamento o a limare la decorazione.'),
  (182, 'arte-gare', 'In una gara Nailympia, cosa succede se pulisci le unghie della modella dopo lo stop?', '["Nulla","−5 punti","Squalifica","Bonus di pulizia"]'::jsonb, 2, 'Pulire mani o unghie con qualsiasi prodotto dopo la chiusura porta alla squalifica.'),
  (183, 'arte-gare', 'Nella scheda Nailympia 2026 French Twist 3 forme, quanto vale l''apex?', '["30 punti da solo","15 punti, valutato con la curva C dallo stesso giudice","5 punti","Non è valutato"]'::jsonb, 1, 'Il giudice 3 assegna 15 punti alla curva C e 15 all''apex: 30 in tutto.'),
  (184, 'arte-gare', 'Il gel cat-eye va "flashato" pochi secondi subito dopo il magnete perché:', '["Si secca il pennello","Le particelle continuano a muoversi e il disegno si perde","Il magnete si scarica","Il top non serve"]'::jsonb, 1, 'Un flash breve, un dito alla volta, fissa le particelle.')
